import React from 'react';
import './ProfileCard.css';

// รับ props แบบ Destructuring และใส่ default value ให้ major
function ProfileCard({ name, nickname, major = 'ยังไม่ระบุสาขา', favorites = [] }) {
  return (
    <div className="profile-card">
      <div className="card-header">
        <h2 className="card-name">{name}</h2>
        <span className="card-nickname">({nickname})</span>
      </div>
      <p className="card-major">🎓 สาขา: {major}</p>

      <div className="card-favorites">
        <strong>❤️ ของที่ชอบ:</strong>
        <ul>
          {favorites.map((fav, index) => (
            <li key={index}>{fav}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}

export default ProfileCard;
